def walk_relative(root):
    """Return all files under root as paths relative to root, sorted."""
    files = []
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in sorted(filenames):
            full = os.path.join(dirpath, name)
            files.append(os.path.relpath(full, root))
    return sorted(files)


def walk_empty_dirs(root):
    """Return empty directories (no entries) under root, relative, outermost first."""
    empties = set()
    for dirpath, dirnames, filenames in os.walk(root, topdown=False):
        if not dirnames and not filenames:
            empties.add(os.path.relpath(dirpath, root))
    return sorted(empties, key=len)

